<template><div class="app-container"><el-alert title="候选审阅只处理同一冻结批次的固定六槽位。选入待拍会服务端冻结标题、来源钩子、变化值和完整口播；退回必须留下原因。不会在这里伪造实发数据。" type="warning" :closable="false" class="mb16"/><el-card shadow="never" class="mb16"><el-form :inline="true"><el-form-item label="内容批次ID"><el-input v-model="briefId" clearable style="width:360px" placeholder="从内容批次点击“审阅候选”进入" /></el-form-item><el-form-item><el-button type="primary" icon="Search" @click="load">加载候选</el-button></el-form-item></el-form><el-descriptions v-if="brief.id" :column="3" border><el-descriptions-item label="问题">{{ brief.problemStatement }}</el-descriptions-item><el-descriptions-item label="变化轴">{{ brief.variantAxis }}</el-descriptions-item><el-descriptions-item label="生成状态">{{ brief.latestJobStatus || '未请求' }}</el-descriptions-item></el-descriptions><div v-if="brief.id && candidates.length===0" class="mt16"><el-button type="primary" :loading="generating" icon="MagicStick" @click="generate" v-hasPermi="['topic:brief:generate']">请求固定6条并启动真实生成</el-button></div></el-card><el-empty v-if="loaded && candidates.length===0" description="本批次尚未产生候选；点击上方按钮会创建固定6槽位，并交给领域异步生成器逐槽执行。"/><el-row v-else :gutter="16"><el-col v-for="c in candidates" :key="c.id" :xs="24" :lg="12" class="mb16"><el-card shadow="hover"><template #header><div class="head"><strong>槽位 {{ String(c.ordinalNo).padStart(2,'0') }}</strong><span><el-tag :type="candidateTag(c.lifecycleStatus)">{{ c.lifecycleStatus }}</el-tag><el-tag class="ml8" effect="plain">{{ c.generationStatus }}</el-tag></span></div></template><h3>{{ c.titleSnapshot || '候选生成中' }}</h3><p><b>来源钩子：</b>{{ c.sourceHook || '-' }}</p><p><b>变化值：</b>{{ c.variantValue || '-' }}</p><el-alert v-if="c.evidenceGapSnapshot" :title="c.evidenceGapSnapshot" type="warning" :closable="false" class="mb12"/><div class="script">{{ c.copySnapshot || '尚未生成完整口播' }}</div><el-divider/><p><b>镜头/证据：</b>{{ c.shootingHintsSnapshot || '-' }}</p><p><b>CTA：</b>{{ c.ctaSnapshot || '-' }}</p><p v-if="c.generationFailureReason" class="danger"><b>失败原因：</b>{{ c.generationFailureReason }}</p><div class="actions"><el-button v-if="selectable(c)" type="primary" icon="Check" @click="openSelect(c)" v-hasPermi="['topic:candidate:select']">选入待拍</el-button><el-button v-if="c.lifecycleStatus==='READY_FOR_REVIEW'" icon="Back" @click="openReturn(c)" v-hasPermi="['topic:candidate:review']">退回</el-button></div></el-card></el-col></el-row><el-dialog title="选入待拍" v-model="selectOpen" width="560px"><el-alert title="保存后会新建待拍项并冻结当前标题、来源钩子、变化值和完整口播；这些冻结内容不能在待拍台账中覆盖。" type="info" :closable="false" class="mb16"/><el-form><el-form-item label="优先拍摄原因" required><el-input v-model="selectionReason" type="textarea" :rows="4" placeholder="例如：最贴近本期问题，来源钩子和客户事实均已核对"/></el-form-item></el-form><template #footer><el-button type="primary" @click="submitSelect">确认选入待拍</el-button><el-button @click="selectOpen=false">取消</el-button></template></el-dialog><el-dialog title="退回候选" v-model="returnOpen" width="560px"><el-form><el-form-item label="退回原因" required><el-input v-model="returnReason" type="textarea" :rows="4" placeholder="说明为什么不采用，供下一次生成或审核使用"/></el-form-item></el-form><template #footer><el-button type="primary" @click="submitReturn">确认退回</el-button><el-button @click="returnOpen=false">取消</el-button></template></el-dialog></div></template>
<script setup lang="ts">import { getCurrentInstance, ref } from 'vue'; import type { ComponentInternalInstance } from 'vue'; import { useRoute } from 'vue-router'; import { generateTopicContentBrief, getTopicContentBrief, listTopicContentCandidate, returnTopicContentCandidate, selectTopicContentCandidate } from '@/api/topic/contentBrief'; import type { TopicContentBrief, TopicContentCandidate } from '@/types'; const { proxy }=getCurrentInstance() as ComponentInternalInstance; const route=useRoute(); const briefId=ref(String(route.query.briefId||''));const brief=ref<TopicContentBrief>({}),candidates=ref<TopicContentCandidate[]>([]),loaded=ref(false),generating=ref(false),selectOpen=ref(false),returnOpen=ref(false),current=ref<TopicContentCandidate>({}),selectionReason=ref(''),returnReason=ref(''); let pollTimer:number|undefined; function load(){if(!briefId.value){proxy?.$modal.msgWarning('请从内容批次选择一个已冻结批次');return} Promise.all([getTopicContentBrief(briefId.value),listTopicContentCandidate(briefId.value)]).then(([b,c])=>{brief.value=b.data||{};candidates.value=c.data||[];loaded.value=true;if(brief.value.latestJobStatus==='QUEUED'||brief.value.latestJobStatus==='RUNNING'){window.clearTimeout(pollTimer);pollTimer=window.setTimeout(load,3000)}})}function generate(){generating.value=true;generateTopicContentBrief(briefId.value).then(()=>{proxy?.$modal.msgSuccess('固定6槽位已进入异步生成，请等待逐槽状态更新');load()}).finally(()=>generating.value=false)}function selectable(c:TopicContentCandidate){return c.lifecycleStatus==='READY_FOR_REVIEW'||c.lifecycleStatus==='RETURNED'}function openSelect(c:TopicContentCandidate){current.value=c;selectionReason.value='';selectOpen.value=true}function openReturn(c:TopicContentCandidate){current.value=c;returnReason.value='';returnOpen.value=true}function submitSelect(){if(!selectionReason.value.trim()){proxy?.$modal.msgWarning('请填写优先拍摄原因');return}selectTopicContentCandidate(current.value.id as string,selectionReason.value).then(()=>{proxy?.$modal.msgSuccess('已选入待拍，冻结快照已建立');selectOpen.value=false;load()})}function submitReturn(){if(!returnReason.value.trim()){proxy?.$modal.msgWarning('请填写退回原因');return}returnTopicContentCandidate(current.value.id as string,returnReason.value).then(()=>{proxy?.$modal.msgSuccess('候选已退回并保留原因');returnOpen.value=false;load()})}function candidateTag(s?:string){return s==='SELECTED_FOR_SHOOT'?'success':s==='RETURNED'?'info':s==='EVIDENCE_INSUFFICIENT'?'warning':''}if(briefId.value)load();</script><style scoped>.head,.actions{display:flex;justify-content:space-between;align-items:center}.script{white-space:pre-wrap;line-height:1.75;background:#f8fafc;padding:12px;border-radius:4px;max-height:260px;overflow:auto}.ml8{margin-left:8px}.mb12{margin-bottom:12px}.mt16{margin-top:16px}.danger{color:#f56c6c}</style>
